import {gatheringCases,gatheringCase,emptyBasket,basketStatus,adjustBasket,checkBasket} from './gathering-budget-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,owner=null;
export function resetGatheringBudget(){visit=null;owner=null;}
export function gatheringBudgetSession(){return visit?structuredClone(visit):null;}
function current(explorerId){if(owner!==explorerId){resetGatheringBudget();owner=explorerId;}return visit;}
const draft=()=>visit?.cases[visit.caseId]||null;
const plural=(n,one,many)=>`${n} ${n===1?one:many}`;
const unit=(c,index,n)=>plural(n,c.needs[index].singular,c.needs[index].name.toLowerCase());
const button=(attr,label,cls='secondary',disabled=false)=>`<button type="button" class="${cls}" ${attr}${disabled?' disabled':''}>${esc(label)}</button>`;

const drawings={
 'plain-card':'<rect x="18" y="12" width="33" height="37" rx="3" fill="#e9c66e" stroke="#514c39" stroke-width="2"/>',
 'folded-pair':'<rect x="7" y="15" width="27" height="35" rx="3" fill="#f0d88f" stroke="#514c39" stroke-width="2"/><rect x="33" y="8" width="27" height="35" rx="3" fill="#e9c66e" stroke="#514c39" stroke-width="2"/>',
 'paper-sign':'<rect x="8" y="11" width="53" height="35" rx="3" fill="#f1d2a5" stroke="#704c33" stroke-width="2"/><path d="M14 19h40M14 27h28M14 35h37" stroke="#704c33" stroke-width="2"/>',
 'leaf-sign':'<path d="M12 42Q13 13 56 12Q51 39 12 42Z" fill="#abc884" stroke="#3e6645" stroke-width="2"/><path d="M14 42L48 19" stroke="#3e6645" stroke-width="2"/>',
 'star-marker':'<path d="M34 5l7 16 17 2-13 11 4 17-15-9-15 9 4-17-13-11 17-2Z" fill="#a9bfd9" stroke="#385a78" stroke-width="2"/>',
 'diamond-pair':'<path d="M20 7L34 27 20 47 6 27Z" fill="#e7bd6d" stroke="#705633" stroke-width="2"/><path d="M48 7L62 27 48 47 34 27Z" fill="#e7bd6d" stroke="#705633" stroke-width="2"/>',
 'map-copy':'<path d="M10 11l16-4 16 5 16-5v41l-16 5-16-5Z" fill="#d1e1ce" stroke="#4b7053" stroke-width="2"/><path d="M26 7v41m16-36v41" stroke="#4b7053"/>',
 'map-pair':'<path d="M5 16l14-4 14 4v31l-14 4-14-4Z" fill="#d1e1ce" stroke="#4b7053" stroke-width="2"/><path d="M35 11l14-4 14 4v31l-14 4-14-4Z" fill="#d1e1ce" stroke="#4b7053" stroke-width="2"/>'
};
const packetArt=item=>`<svg viewBox="0 0 68 58" aria-hidden="true">${drawings[item.id]}</svg>`;
function catalog(){return gatheringCases.map(c=>button(`data-gather-start="${c.id}"`,'Choose this request: '+c.title+'. '+c.request,'secondary')).join('');}
function requestCard(c){return `<section class="gather-request"><div class="gather-request-head"><span class="gather-limit" aria-label="Limit ${c.limit} pretend cents">${c.limit}¢</span><div><p class="gather-eyebrow">Current request</p><h2>${esc(c.title)}</h2></div></div><p>${esc(c.request)}</p><div class="gather-needs">${c.needs.map(n=>`<span>At least ${n.minimum} ${esc(n.minimum===1?n.singular:n.name.toLowerCase())}</span>`).join('')}</div>${hearButton(c.request,'Hear the request')}<details class="gather-chooser"><summary>Choose another request</summary><p>Each request stays open. Baskets are only for this screen visit.</p>${catalog()}</details></section>`;}
function basketPicture(c,w,s){
 const chosen=w.counts.flatMap((n,i)=>Array.from({length:n},()=>`<li class="gather-chip">${packetArt(c.items[i])}<span>${esc(c.items[i].name)} · ${c.items[i].price}¢ per packet</span></li>`)).join('');
 return `<section class="gather-summary"><h3>Our pictured basket</h3>${chosen?`<ul class="gather-chips" aria-label="Selected packets">${chosen}</ul>`:'<p>The basket is empty. Add any packet to try a plan.</p>'}<dl>${c.needs.map((n,i)=>`<div><dt>${esc(n.name)}</dt><dd>${s.have[i]} of at least ${n.minimum}</dd></div>`).join('')}<div><dt>Basket cost</dt><dd>${s.cost}¢ of ${c.limit}¢ available</dd></div></dl><p class="tiny">These totals come from the pictured packets. They are separate from your cost idea.</p></section>`;
}
function stockCard(c,w,item,i){const units=item.units.map((n,k)=>n?unit(c,k,n):'').filter(Boolean).join(' and '),count=w.counts[i];return `<div class="gather-stock"><div class="gather-packet" role="img" aria-label="One packet of ${esc(item.name)} brings ${esc(units)}">${packetArt(item)}</div><div><strong>${esc(item.name)} · ${item.price}¢ per packet</strong><p class="tiny">Brings ${esc(units)}. At this stall: ${plural(item.stock,'packet','packets')}.</p></div><div class="gather-stock-controls">${button(`data-gather-change="${item.id},-1" aria-label="Remove one ${esc(item.name)} packet"`,'Remove','secondary',count===0)}${button(`data-gather-change="${item.id},1" aria-label="Add one ${esc(item.name)} packet"`,'Add','secondary',count===item.stock)}<span>In our basket: ${plural(count,'packet','packets')}</span></div></div>`;}
function feedback(c,s){const idea=s.idea===null?'No cost idea was checked. The basket was still checked.':`Your cost idea was ${s.idea}¢. The pictured packets total ${s.cost}¢. ${s.ideaFit?'The idea matches the packet total.':'The idea can be revised without changing the basket.'}`;
 return `<div class="gather-feedback" id="gather-feedback" role="status" tabindex="-1"><p>${s.budgetFit?`The packets cost ${s.cost}¢. That is within the ${c.limit}¢ limit; ${s.left}¢ is unspent.`:`The packets cost ${s.cost}¢, which is ${s.over}¢ above the ${c.limit}¢ limit. Try a different packet choice.`}</p>${c.needs.map((n,i)=>`<p>${esc(n.name)}: ${s.have[i]} of at least ${n.minimum}. ${s.have[i]>=n.minimum?'This part of the request is met.':`This part still needs ${n.minimum-s.have[i]}.`}</p>`).join('')}<p><strong>${s.working?'This is one working plan for the pretend gathering. You can keep exploring other choices.':'This basket can be revised. The cost limit and the requested supplies are separate checks.'}</strong></p><p>${idea}</p></div>`;}
function basketTurn(c,w,s){return `<div class="gather-layout"><section class="gather-panel"><h2 id="gather-turn-title" tabindex="-1">Make a basket</h2><p>Add or remove whole packets. A price is for one packet.</p><div class="gather-stock-list">${c.items.map((item,i)=>stockCard(c,w,item,i)).join('')}</div></section><div>${basketPicture(c,w,s)}${button('data-gather-page="review"','Check this plan','primary')}</div></div>`;}
function reviewTurn(c,w,s){return `<section class="gather-panel gather-review"><h2 id="gather-turn-title" tabindex="-1">Check a plan</h2><p>Look at the same basket. The cost limit and the requested supplies are two separate checks.</p>${basketPicture(c,w,s)}<label for="gather-idea">What do you think these packets cost in all?</label><div class="gather-idea-row"><input id="gather-idea" type="text" inputmode="numeric" maxlength="2" value="${esc(w.idea)}" aria-describedby="gather-idea-help"><span>pretend cents</span>${button('data-gather-mode="unsure" aria-pressed="'+(w.mode==='unsure')+'"','Not sure')}${button('data-gather-mode="blank" aria-pressed="'+(w.mode==='blank')+'"','Leave blank')}</div><p id="gather-idea-help" class="tiny">Optional. The basket is checked even without a cost idea.</p><div class="gather-review-actions">${button('data-gather-check','Check basket and idea','primary')}${button('data-gather-page="basket"','Return to basket')}</div><p id="gather-status" role="status" tabindex="-1">${visit.checked?'':'The plan can be checked or revised whenever you like.'}</p>${visit.checked?feedback(c,visit.checked):''}<details class="gather-help"><summary>Why might a swap help?</summary><p>Count what each packet brings. Add each selected packet price once. Compare the cost with the limit, then compare the supplied counts with the request. A swap can change both.</p><p>A rehearsal table has a 5¢ limit. A 2¢ tag and a 3¢ ribbon cost 5¢ together. If it also needs a sign, that basket still misses its request.</p></details><p class="tiny">Which packet would you swap, and what would change in the cost or the supplies?</p></section>`;}
export function gatheringBudgetPage(explorerId){
 const v=current(explorerId),c=gatheringCase(v?.caseId),w=c?draft():null,s=w?basketStatus(c,w.counts):null;
 const body=c&&w&&s?`${requestCard(c)}<nav class="gather-turns" aria-label="Planning turns">${button(`data-gather-page="basket" aria-current="${v.page==='basket'?'page':'false'}"`,'1. Make a basket')}${button(`data-gather-page="review" aria-current="${v.page==='review'?'page':'false'}"`,'2. Check a plan')}</nav>${v.page==='basket'?basketTurn(c,w,s):reviewTurn(c,w,s)}`:`<section class="gather-panel"><h2 id="gather-chooser-title" tabindex="-1">Choose a gathering request</h2><p>Both requests are open. Each has more than one working plan.</p><div class="gather-catalog">${catalog()}</div></section>`;
 return `<div class="gather-budget-page"><header class="page-heading"><a class="back" href="#workshop">← Back to the Workshop</a><p class="gather-eyebrow">Pretend planning table</p><h1>Gathering Budget</h1><p>Choose supplies for a make-believe welcome. More than one basket can work.</p></header>${body}<p class="gather-lifecycle">This table is for this visit. Leaving or reloading starts an empty basket. Your other garden work stays saved as before.</p><details class="gather-grownup"><summary>For grown-ups</summary><p>Pretend prices and packets make this a planning model. Families make real choices for many reasons. This activity does not judge those choices. No basket, cost idea or support is saved here.</p></details></div>`;
}
export function bindGatheringBudget({render,focus,explorerId}){
 const root=document.querySelector('.gather-budget-page');if(!root)return;
 const capturedOwner=explorerId(),capturedVisit=current(capturedOwner);
 const live=()=>root.isConnected&&location.hash==='#workshop/budget'&&explorerId()===capturedOwner&&owner===capturedOwner&&visit===capturedVisit;
 const redraw=selector=>{render();focus(selector);};
 root.querySelectorAll('[data-gather-start]').forEach(b=>b.addEventListener('click',()=>{if(!root.isConnected||location.hash!=='#workshop/budget'||explorerId()!==capturedOwner||owner!==capturedOwner||visit!==capturedVisit)return;const c=gatheringCase(b.dataset.gatherStart);if(!c)return;const cases={...(visit?.cases||{})};cases[c.id]??={counts:emptyBasket(),idea:'',mode:'blank'};visit={caseId:c.id,page:'basket',cases,checked:null};redraw('#gather-turn-title');}));
 root.querySelectorAll('[data-gather-page]').forEach(b=>b.addEventListener('click',()=>{if(!live()||!['basket','review'].includes(b.dataset.gatherPage))return;visit={...visit,page:b.dataset.gatherPage,checked:null};redraw('#gather-turn-title');}));
 root.querySelectorAll('[data-gather-change]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const [id,raw]=b.dataset.gatherChange.split(','),delta=Number(raw),c=gatheringCase(visit.caseId),w=draft(),next=adjustBasket(c,w.counts,id,delta);if(!next)return;visit={...visit,cases:{...visit.cases,[c.id]:{...w,counts:next}},checked:null};render();const same=`[data-gather-change="${id},${delta}"]:not(:disabled)`,reverse=`[data-gather-change="${id},${-delta}"]:not(:disabled)`;focus(document.querySelector(same)?same:document.querySelector(reverse)?reverse:'#gather-turn-title');}));
 root.querySelector('#gather-idea')?.addEventListener('input',e=>{if(!live())return;const w=draft();w.idea=e.currentTarget.value;w.mode='number';visit.checked=null;root.querySelector('#gather-feedback')?.remove();root.querySelectorAll('[data-gather-mode]').forEach(b=>b.setAttribute('aria-pressed','false'));root.querySelector('#gather-status').textContent='The plan changed. Check this version when you like.';});
 root.querySelectorAll('[data-gather-mode]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const mode=b.dataset.gatherMode;if(!['blank','unsure'].includes(mode))return;const w=draft();visit={...visit,cases:{...visit.cases,[visit.caseId]:{...w,idea:'',mode}},checked:null};redraw('#gather-idea');}));
 root.querySelector('[data-gather-check]')?.addEventListener('click',()=>{if(!live())return;const c=gatheringCase(visit.caseId),w=draft(),checked=checkBasket(c,w.counts,w.idea,w.mode);if(!checked){const note=root.querySelector('#gather-status');note.textContent='Use up to two digits for a cost idea, or choose Not sure. The basket was not checked yet.';focus('#gather-idea');return;}visit={...visit,checked};redraw('#gather-feedback');});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
}
